#!/usr/bin/env node
// @ts-nocheck — runs under tsx. Proves PRODUCT D7 SLICE 3: regression/change monitoring between two ai-assurance
// reports. Detects PASS→FAIL / ASSURED→NOT_ASSURED / technical exit0→1 / evidence fresh→stale / integrity breaks;
// fail-closed (a tampered or non-report ⇒ never 'no regression'); exit codes 0/1/2. Reports generated by the real
// buildAssuranceReport; distinct timestamps so a normal version bump isn't mistaken for a same-version tamper.
"use strict";
const assert = require("assert");
const REP = require("./ai-assurance-report.js");
const REG = require("./ai-assurance-regression.js");
const prov = require("./evidence-provenance.js");
let pass = 0; const ok = (n, c) => { assert.ok(c, n); console.log("  ok -", n); pass++; };

const verifiedProfile = { tenantId: "t1", country: "FR", processesEUPersonalData: true, targetFrameworks: ["GDPR"],
  declaredEvidence: [{ id: "E1", obligationId: "GDPR-ROPA", tenantId: "t1" }, { id: "E2", obligationId: "GDPR-LAWFUL", tenantId: "t1" }, { id: "E3", obligationId: "GDPR-BREACH", tenantId: "t1" }] };
const verifier = () => ({ verified: true });
const mk = (over) => REP.buildAssuranceReport({ system: { id: "s1", activities: {}, profile: verifiedProfile }, verifier,
  technical: { dependencies: [{ name: over.dep || "mit-lib", license: over.lic || "MIT" }], tests: { total: 10, passing: 10 } },
  evidenceControls: [{ ref: "ROPA", operationalEvidenceAt: over.evAt || "2026-10-01" }], ttlDays: 90, now: over.now }).report;

// (1) baseline ASSURED vs a later report with a GPL dep ⇒ technical regression ⇒ REGRESSION, exit 1.
{
  const before = mk({ now: "2026-10-28" });
  const after = mk({ now: "2026-10-29", dep: "gpl-lib", lic: "GPL-3.0" });
  const r = REG.compareReports(before, after);
  ok("ASSURED→NOT_ASSURED via GPL dep ⇒ REGRESSION (exit 1), overall+technical regressions flagged",
     before.overall === "ASSURED_TECHNICAL" && r.verdict === "REGRESSION" && r.exitCode === 1 && r.regressions.some((x) => x.kind === "technical") && r.regressions.some((x) => x.kind === "overall"));
}
// (2) evidence fresh→stale ⇒ freshness regression ⇒ REGRESSION.
{
  const before = mk({ now: "2026-10-28" });
  const after = mk({ now: "2026-10-29", evAt: "2020-01-01" });   // stale
  const r = REG.compareReports(before, after);
  ok("evidence fresh→stale ⇒ REGRESSION (freshness regression flagged)", r.verdict === "REGRESSION" && r.regressions.some((x) => x.kind === "evidence-freshness"));
}
// (3) IMPROVED: NOT_ASSURED baseline (GPL) → ASSURED (clean) ⇒ IMPROVED, exit 0, no regression.
{
  const before = mk({ now: "2026-10-28", dep: "gpl-lib", lic: "GPL-3.0" });
  const after = mk({ now: "2026-10-29" });
  const r = REG.compareReports(before, after);
  ok("NOT_ASSURED→ASSURED ⇒ IMPROVED (exit 0), no regressions", r.verdict === "IMPROVED" && r.exitCode === 0 && r.regressions.length === 0);
}
// (4) STABLE: two equivalent reports (different timestamps) ⇒ STABLE, exit 0.
{
  const before = mk({ now: "2026-10-28" });
  const after = mk({ now: "2026-10-29" });
  const r = REG.compareReports(before, after);
  ok("equivalent reports (both ASSURED) ⇒ STABLE (exit 0)", r.verdict === "STABLE" && r.exitCode === 0 && r.regressions.length === 0);
}
// (5) INTEGRITY_FAILED: a tampered report (field changed, digest not recomputed) ⇒ exit 2, never 'no regression'.
{
  const before = mk({ now: "2026-10-28" });
  const after = mk({ now: "2026-10-29" });
  after.controlTally = { ...after.controlTally, PASS: (after.controlTally.PASS || 0) + 99 };   // forge PASS count, digest now stale
  const r = REG.compareReports(before, after);
  ok("tampered after-report (stale digest) ⇒ INTEGRITY_FAILED (exit 2), not trusted", r.verdict === "INTEGRITY_FAILED" && r.exitCode === 2 && r.integrity.afterIntact === false);
}
// (6) same generatedAt but different digest ⇒ integrity inconsistency regression.
{
  const before = mk({ now: "2026-10-29" });
  const after = mk({ now: "2026-10-29", dep: "gpl-lib", lic: "GPL-3.0" });   // same timestamp, different content ⇒ different digest
  const r = REG.compareReports(before, after);
  ok("same generatedAt + different digest ⇒ integrity regression flagged", r.regressions.some((x) => x.kind === "integrity"));
}
// (7) cannot compare a non-report ⇒ INVALID_INPUT, exit 2 (fail-closed, never STABLE).
{
  const r = REG.compareReports({}, mk({ now: "2026-10-29" }));
  ok("non-report input ⇒ INVALID_INPUT (exit 2), never STABLE", r.ok === false && r.code === "INVALID_INPUT" && r.exitCode === 2);
}
// (8) verifyReportIntegrity: intact report verifies true; mutated verifies false.
{
  const rep = mk({ now: "2026-10-29" });
  const tampered = { ...rep, overall: "FORGED_STATUS" };
  ok("verifyReportIntegrity: intact true, mutated false", REG.verifyReportIntegrity(rep) === true && REG.verifyReportIntegrity(tampered) === false);
}

// (9) REGRESSION-TEST for audit defect D1: a digest-STRIPPED report (unverifiable) must fail closed, NOT be trusted as
// STABLE. Forge an ASSURED 'after' back over a genuinely-regressed one and delete its digest ⇒ INTEGRITY_FAILED, exit 2.
{
  const before = mk({ now: "2026-10-28" });
  const regressed = mk({ now: "2026-10-29", dep: "gpl-lib", lic: "GPL-3.0" });   // genuinely NOT_ASSURED
  const forged = { ...regressed, overall: before.overall, technical: before.technical, controlTally: before.controlTally };
  delete forged.integrityDigest;   // strip the digest to dodge the tamper-check
  const r = REG.compareReports(before, forged);
  ok("digest-STRIPPED (unverifiable) report ⇒ INTEGRITY_FAILED (exit 2), never STABLE — fail-closed (audit D1)",
     r.verdict === "INTEGRITY_FAILED" && r.exitCode === 2 && r.integrity.afterIntact === false);
}
// (10) technical PASS→INSUFFICIENT_EVIDENCE counts as a regression (audit D4).
{
  const before = mk({ now: "2026-10-28" });
  const after = mk({ now: "2026-10-29" });
  after.technical = { ...after.technical, status: "INSUFFICIENT_EVIDENCE" };
  after.integrityDigest = prov.contentDigest((() => { const c = { ...after }; delete c.integrityDigest; return c; })());   // re-stamp so it stays verifiable
  const r = REG.compareReports(before, after);
  ok("technical PASS→INSUFFICIENT_EVIDENCE ⇒ REGRESSION (audit D4)", r.verdict === "REGRESSION" && r.regressions.some((x) => x.kind === "technical" && /INSUFFICIENT/.test(x.detail)));
}

console.log(`\nAI-ASSURANCE-REGRESSION suite — ${pass} assertions passed. (PASS→FAIL / ASSURED→NOT_ASSURED / technical exit0→1 / fresh→stale / integrity break detected; fail-closed non-report+tamper; exit 0/1/2)`);
